package com.compiler.model;

import java.util.Objects;

/**
 * Represents a token generated by the lexical analyzer.
 * Contains token type, matched lexeme, 1-based line and column positions.
 */
public class Token {
    private final TokenType type;
    private final String lexeme;
    private final int line;
    private final int column;
    private final String detail;

    public Token(TokenType type, String lexeme, int line, int column) {
        this(type, lexeme, line, column, "");
    }

    public Token(TokenType type, String lexeme, int line, int column, String detail) {
        this.type = Objects.requireNonNull(type, "type cannot be null");
        this.lexeme = lexeme != null ? lexeme : "";
        this.line = line;
        this.column = column;
        this.detail = detail != null ? detail : "";
    }

    public TokenType getType() {
        return type;
    }

    public String getTypeName() {
        return type.getTypeName();
    }

    public String getLexeme() {
        return lexeme;
    }

    public int getLine() {
        return line;
    }

    public int getColumn() {
        return column;
    }

    public String getCategory() {
        return type.getCategory().getLabel();
    }

    public String getCategoryColor() {
        return type.getCategory().getColorHex();
    }

    public String getDetail() {
        return detail;
    }

    public boolean isError() {
        return type == TokenType.ERROR;
    }

    @Override
    public String toString() {
        return String.format("%-12s | %-15s | %-4d | %-4d",
                type.getTypeName(), lexeme, line, column);
    }
}
